import static org.junit.jupiter.api.Assertions.assertEquals;

class ProcessorTemplateHandlerHandleStandaloneElementTests {

    @Test
    void processesStandaloneElementThroughItsAssociatedTagProcessor() {
        final TemplateEngine templateEngine = new TemplateEngine();

        final StringTemplateResolver resolver = new StringTemplateResolver();
        resolver.setTemplateMode(TemplateMode.HTML);
        resolver.setCacheable(false);
        templateEngine.setTemplateResolver(resolver);
        templateEngine.addDialect(new StandaloneElementDialect());

        final String result = templateEngine.process("<x:item/>", new Context());

        assertEquals("processed", result);
    }

    private static final class StandaloneElementDialect extends AbstractProcessorDialect {

        private StandaloneElementDialect() {
            super("Standalone test dialect", "x", 1000);
        }

